t l.lanname = 'plpgsql' from pg_proc f join pg_language l on l.oid = f.prolang where f.oid = to_regprocedure('public.storage_reserved_upload(text,text)')), false) and coalesce((select l.lanname = 'plpgsql' from pg_proc f join pg_language l on l.oid = f.prolang where f.oid = to_regprocedure('public.get_creator_storage_usage(uuid)')), false) as p15_upload_functions, coalesce((select not public from storage.buckets where id = 'digital-products'), false) and coalesce((select allowed_mime_types is not null from storage.buckets where id = 'avatars'), false) as p16_buckets, to_regclass('public.idx_digital_assets_file_path') is not null as p17_assets_server_only, coalesce((select l.lanname = 'plpgsql' from pg_proc f join pg_language l on l.oid = f.prolang where f.oid = to_regprocedure('public.storage_cleanup_candidates(integer,integer)')), false) as p18_cleanup_functions, exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'product_variants' and policyname like 'Creators can view their own variants%') as p19_variant_policies, exists (select 1 from pg_index i where i.indrelid = to_regclass('public.payment_methods') and i.indisunique and i.indpred is null and (select string_agg(a.attname, ',' order by a.attname) from pg_attribute a where a.attrelid = i.indrelid and a.attnum = any (i.indkey::int2[])) = 'stripe_payment_method_id') and (select column_default from information_schema.columns where table_schema = 'public' and table_name = 'payment_methods' and column_name = 'type') is not null and (select is_nullable from information_schema.columns where table_schema = 'public' and table_name = 'email_events' and column_name = 'creator_id') = 'YES' and exists (select 1 from pg_constraint where conname = 'email_events_event_type_check' and pg_get_constraintdef(oid) like '%failed%') and not coalesce((select bool_or(case when exists (select 1 from pg_roles where rolname = 'anon') then has_function_privilege('anon', f.oid, 'execute') else false end) from pg_proc f join pg_namespace n on n.oid = f.pronamespace where n.nspname = 'public' and f.proname = 'exec_sql'), false) and to_regprocedure('public.search_products_ranked(text,text,text,integer,integer)') is not null as p20_cards_bounces_exec_sql, exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'timezone') and (to_regclass('public.push_tokens') is null or exists (select 1 from pg_constraint where conname = 'push_tokens_platform_check' and pg_get_constraintdef(oid) like '%web%')) as p23_push_time_zone, to_regclass('public.theme_chat_conversations') is not null and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'theme_chat_messages' and column_name = 'conversation_id') and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'theme_chat_conversations' and policyname = 'tcc_own_read') as p24_theme_chat_conversations, exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'storelib owner read public buckets%') and exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'storelib owner insert public buckets%') and exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'storelib owner update public buckets%') and exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'storelib owner delete public buckets%') and exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'storelib owner reserved read digital-products%') and exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'storelib owner reserved insert digital-products%') and exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'storelib owner reserved update digital-products%') and not exists (select 1 from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and not (p.roles <@ array['service_role']::name[]) and ((p.policyname like 'storelib owner %' and not (p.policyname like any (array['storelib owner read public buckets%', 'storelib owner insert public buckets%', 'storelib owner update public buckets%', 'storelib owner delete public buckets%', 'storelib owner reserved read digital-products%', 'storelib owner reserved insert digital-products%', 'storelib owner reserved update digital-products%']))) or (p.policyname not like 'storelib owner %' and (exists (select 1 from unnest(array['digital-products', 'product-files', 'digital-assets', 'product-images', 'avatars', 'covers', 'store-builder-images', 'onepage-assets', 'lead-form-files-v2', 'lead-form-files', 'product-videos', 'email-images']) as mb where position(quote_literal(mb) in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) > 0) or position('bucket_id' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) = 0)))) as p90_storage_policies;
